 resources.push({id:slug(t.title),type:'tutoriel',title:t.title.replace(/en 15 minutes/,'pas à pas').replace(/en 5 minutes/,'pas à pas'),desc:t.objective,category:cats[t.cat],objective:cats[t.cat],discipline:t.cat==='math'?'Mathématiques':'Toutes disciplines',level:'Collège et lycée',difficulty:t.diff==='debutant'?'Débutant':'Intermédiaire',language:'Français',cost:'Gratuit',media:t.cat==='visual'?'Présentation':'Texte',duration:t.duration+' de préparation indicative',tools:t.tools,steps,expected:t.result,pitfall:t.pitfall,reviewed:date,tags:[cats[t.cat],'préparation','tutoriel']});
